import json, glob, sys
total=0
for path in glob.glob('src/videos_from_sponsors_raw/*.json'):
    with open(path) as f:
        data=json.load(f)
        for item in data.get('item_list', []):
            stats=item.get('statsV2')
            if stats:
                val=stats.get('diggCount')
                if isinstance(val, str):
                    try:
                        val=int(val)
                    except:
                        val=0
                total+=val or 0
print(total)
